#!/usr/bin/env node
/**
 * push.mjs — put the All-on-X quiz combo on the Arvada Dental Center Webflow site.
 *
 * Each page is three parts, generated by 04-design/.tmp/aox-quiz/build.mjs into out/:
 *   <key>.head.html    noindex + the stylesheet   -> page head custom code
 *   <key>.embed.html   the markup                 -> one Embed element in the body
 *   <key>.footer.html  the scripts                -> page footer custom code
 *
 * This design cannot take the v2 native route (../v2-native): the quiz is
 * script and the stylesheet uses pseudo-elements, clamp() and masks, which
 * data_whtml_builder refuses. The markup stays in ONE Embed so the Designer
 * shows the page and the team can open the code.
 *
 *   node push.mjs                 # create what is missing, write all three parts, read each back
 *   node push.mjs thanks          # one page
 *   node push.mjs --publish       # then publish to the webflow.io staging subdomain ONLY
 *
 * Idempotent. It never publishes to a custom domain: that is a separate, explicit go-ahead.
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { wf, must, SITE } from './wfq.mjs';

const HERE = fileURLToPath(new URL('.', import.meta.url));
const OUT = join(HERE, 'out');
const FOLDER = '6a84bf58bb34580fa5c65306';                 // /ads-landing-pages
const STATE = join(HERE, 'pages-built.json');
const manifest = JSON.parse(readFileSync(join(OUT, 'manifest.json'), 'utf8'));
const state = existsSync(STATE) ? JSON.parse(readFileSync(STATE, 'utf8')) : {};
const save = () => writeFileSync(STATE, JSON.stringify(state, null, 1) + '\n');

const args = process.argv.slice(2);
const PUBLISH = args.includes('--publish');
const keys = args.filter((a) => !a.startsWith('--'));
const todo = keys.length ? keys : Object.keys(manifest);
const part = (key, name) => readFileSync(join(OUT, `${key}.${name}.html`), 'utf8');

/** Depth-first search of a get_all_elements result for the nodes a predicate accepts. */
function findAll(node, pred, acc = []) {
  if (Array.isArray(node)) { for (const n of node) findAll(n, pred, acc); return acc; }
  if (node && typeof node === 'object') {
    if (node.id && typeof node.id === 'object' && pred(node)) acc.push(node);
    for (const k of Object.keys(node)) if (k !== 'id') findAll(node[k], pred, acc);
  }
  return acc;
}

for (const key of todo) {
  const m = manifest[key];
  console.log(`\n── ${key}  /ads-landing-pages/${m.slug}`);
  state[key] ??= { slug: m.slug };
  const st = state[key];

  /* 1. the page */
  if (!st.pageId) {
    const existing = JSON.parse(readFileSync(join(HERE, 'pages.json'), 'utf8')).find((p) => p.slug === m.slug);
    if (existing) { st.pageId = existing.id; console.log(`  page exists ${st.pageId}`); }
    else {
      const [r] = must(await wf('data_pages_tool', [{ label: 'create', create_page: {
        site_id: SITE, title: m.title, slug: m.slug, parentFolderId: FOLDER,
        seo: { title: m.title, description: m.description },
      } }]), 'create_page');
      st.pageId = r.result?.id ?? r.result?.page?.id;
      if (!st.pageId) throw new Error('create_page returned no id: ' + JSON.stringify(r).slice(0, 600));
      console.log(`  page created ${st.pageId}`);
    }
    save();
  }

  /* 2. head and footer code */
  for (const location of ['head', 'footer']) {
    const content = part(key, location);
    must(await wf('data_scripts_tool', [{ label: location, set_page_freeform_code: { page_id: st.pageId, location, content } }]), `set ${location}`);
    const [back] = must(await wf('data_scripts_tool', [{ label: location, get_page_freeform_code: { page_id: st.pageId, location } }]), `read ${location}`);
    const stored = (Array.isArray(back.result) ? back.result : [back.result]).find((b) => b.location === location)?.content ?? '';
    if (stored !== content) throw new Error(`${key} ${location}: stored code differs from source (${stored.length} vs ${content.length} chars)`);
    console.log(`  ${location} code  ${content.length} chars, read back identical`);
  }

  /* 3. the Embed */
  const embed = part(key, 'embed');
  const [tree] = must(await wf('data_element_tool', [{ label: 'tree', get_all_elements: { depth: -1 } }], { pageId: st.pageId }), 'get_all_elements');
  const embeds = findAll(tree, (n) => /HtmlEmbed/i.test(String(n.type)));
  let target = embeds[0]?.id;
  if (!target) {
    const body = findAll(tree, (n) => /^Body$/i.test(String(n.type)))[0];
    if (!body) throw new Error('no Body element on the page: ' + JSON.stringify(tree).slice(0, 500));
    const [b] = must(await wf('data_element_builder', [{
      build_label: 'embed', parent_element_id: body.id, creation_position: 'append',
      element_schema: { type: 'HtmlEmbed' },
    }], { pageId: st.pageId }), 'create embed');
    target = findAll(b, (n) => true)[0]?.id;
    if (!target) throw new Error('embed created but no id returned: ' + JSON.stringify(b).slice(0, 600));
    console.log('  embed created');
  }
  st.embedId = target;
  save();
  must(await wf('data_element_settings_tool', [{ label: 'code', set_settings: { operations: [{
    label: 'code', element_id: target, settings: [{ key: 'code', static_text: { value: embed } }],
  }] } }], { pageId: st.pageId }), 'set embed code');
  const [got] = must(await wf('data_element_settings_tool', [{ label: 'read', get_settings: { type: 'all_raw_settings', element_id: target } }], { pageId: st.pageId }), 'read embed code');
  const stored = JSON.stringify(got).includes(JSON.stringify(embed).slice(1, -1));
  if (!stored) throw new Error(`${key} embed: stored code differs from source`);
  console.log(`  embed code  ${embed.length} chars, read back identical`);
  st.pushedAt = new Date().toISOString();
  save();
}

if (PUBLISH) {
  const [r] = must(await wf('data_sites_tool', [{ label: 'publish', publish_site: { site_id: SITE, publishToWebflowSubdomain: true, customDomains: [] } }]), 'publish');
  console.log('\npublished to the webflow.io subdomain only: ' + JSON.stringify(r.result ?? r).slice(0, 300));
}
